package retry

import("context";"errors";"testing";"time")
var temporary=errors.New("temporary")
func TestRetrySucceedsOnThirdAttempt(t *testing.T){attempts:=0;delays:=[]time.Duration{};policy:=Policy{MaxAttempts:3,Initial:time.Second,Maximum:4*time.Second,Multiplier:2,Retryable:func(err error)bool{return errors.Is(err,temporary)},Sleep:func(_ context.Context,d time.Duration)error{delays=append(delays,d);return nil}};result,err:=Do(context.Background(),policy,func(context.Context)(string,error){attempts++;if attempts<3{return "",temporary};return "ok",nil});if err!=nil||result.Value!="ok"||len(result.Attempts)!=3||len(delays)!=2||delays[0]!=time.Second||delays[1]!=2*time.Second{t.Fatalf("result=%+v delays=%v err=%v",result,delays,err)}}
func TestRetryStopsOnPermanentError(t *testing.T){permanent:=errors.New("permanent");calls:=0;policy:=Policy{MaxAttempts:3,Initial:time.Second,Maximum:time.Second,Multiplier:1,Retryable:func(err error)bool{return false}};result,err:=Do(context.Background(),policy,func(context.Context)(int,error){calls++;return 0,permanent});if !errors.Is(err,permanent)||calls!=1||len(result.Attempts)!=1{t.Fatalf("calls=%d result=%+v err=%v",calls,result,err)}}
func TestRetryCancellationInterruptsBackoff(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());policy:=Policy{MaxAttempts:3,Initial:time.Hour,Maximum:time.Hour,Multiplier:1,Retryable:func(error)bool{return true},Sleep:func(ctx context.Context,_ time.Duration)error{cancel();return ctx.Err()}};_,err:=Do(ctx,policy,func(context.Context)(int,error){return 0,temporary});if err==nil{t.Fatal("cancellation ignored")}}
